class Solution:
    def findMedianSortedArrays(self, nums1: list[int], nums2: list[int]) -> float:
        m, n = len(nums1), len(nums2)
        N = m + n
        half = N // 2

        i = j = 0
        prev = curr = 0.0

        # Iterate up to the median position (half + 1 times)
        for _ in range(half + 1):
            prev = curr

            # Check if nums1 is exhausted or if nums1[i] is smaller than nums2[j]
            if i < m and (j >= n or nums1[i] <= nums2[j]):
                curr = nums1[i]
                i += 1
            else:
                curr = nums2[j]
                j += 1

        # If total length is odd, the current element (curr) is the median
        if N % 2 == 1:
            return curr
        # If total length is even, the median is the average of the current (curr) and previous (prev)
        else:
            return (prev + curr) / 2.0
